function validate([prices, profits]) {
  if (!Array.isArray(prices) || !Array.isArray(profits)) return 'prices and profits must be arrays.';
  if (prices.length !== profits.length) return 'prices and profits need the same length.';
  if (prices.length < 3 || prices.length > 50000) return 'There must be 3 to 50000 items.';
  if (prices.some(v => !Number.isInteger(v) || v < 1 || v > 5000)) return 'Each price is a whole number from 1 to 5000.';
  if (profits.some(v => !Number.isInteger(v) || v < 1 || v > 1000000)) return 'Each profit is a whole number from 1 to 10^6.';
  return null;
}

