function maxProfit(prices, profits) {
  const n = prices.length;
  const maxPrice = prices.reduce((a, b) => Math.max(a, b), 0);

  function update(tree, index, value) {
    for (let i = index; i <= maxPrice; i += i & -i) {
      tree[i] = Math.max(tree[i], value);
    }
  }

  function query(tree, index) {
    let best = 0;
    for (let i = index; i > 0; i -= i & -i) {
      best = Math.max(best, tree[i]);
    }
    return best;
  }

  const leftTree = new Array(maxPrice + 1).fill(0);
  const leftBest = new Array(n).fill(0);
  for (let j = 0; j < n; j++) {
    leftBest[j] = query(leftTree, prices[j] - 1);
    update(leftTree, prices[j], profits[j]);
  }

  const rightTree = new Array(maxPrice + 1).fill(0);
  let answer = -1;
  for (let j = n - 1; j >= 0; j--) {
    const flipped = maxPrice + 1 - prices[j];
    const rightBest = query(rightTree, flipped - 1);
    if (leftBest[j] > 0 && rightBest > 0) {
      answer = Math.max(answer, leftBest[j] + profits[j] + rightBest);
    }
    update(rightTree, flipped, profits[j]);
  }
  return answer;
}

