function maxProfit(prices, profits) {
  // Try every triple of positions and keep the best one with rising prices.
  const n = prices.length;
  let best = -1;
  for (let a = 0; a < n; a++)
    for (let b = a + 1; b < n; b++)
      for (let c = b + 1; c < n; c++)
        if (prices[a] < prices[b] && prices[b] < prices[c])
          best = Math.max(best, profits[a] + profits[b] + profits[c]);
  return best;
}

