function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = 2000;
    const priceCap = rand() < 0.5 ? 5000 : int(3, 40);
    const prices = Array.from({ length: n }, () => int(1, priceCap));
    const profits = Array.from({ length: n }, () => int(1, 1000000));
    return [prices, profits];
  }
  const n = int(3, 9);
  const priceCap = int(1, 6);
  const profitCap = rand() < 0.3 ? 1000000 : int(1, 20);
  const prices = Array.from({ length: n }, () => int(1, priceCap));
  const profits = Array.from({ length: n }, () => int(1, profitCap));
  return [prices, profits];
}
